const input = $json;

const clean = (value) => {
  if (value === undefined || value === null) {
    return null;
  }

  const result = String(value).trim();

  return result === ''
    ? null
    : result;
};

const contactId = clean(input.contact_id);

if (!contactId) {
  throw new Error('contact_id es obligatorio');
}

const uuidPattern =
  /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;

if (!uuidPattern.test(contactId)) {
  throw new Error(
    `contact_id no es un UUID válido: ${contactId}`
  );
}

return [
  {
    json: {
      contact_id: contactId
    }
  }
];

const rows = $json.data ?? [];

if (!Array.isArray(rows)) {
  throw new Error(
    'Respuesta inesperada de Directus al consultar el contacto'
  );
}

if (rows.length === 0) {
  return [
    {
      json: {
        status: 'not_found',
        contact: null,
        primary_phone: null,
        phones: [],
        tasks: [],
        appointments: []
      }
    }
  ];
}

const contact = rows[0];

if (!contact?.id) {
  throw new Error(
    'Directus devolvió un contacto sin id'
  );
}

const phones = Array.isArray(contact.phones)
  ? contact.phones
  : [];

const tasks = Array.isArray(contact.tasks)
  ? contact.tasks
  : [];

const appointments = Array.isArray(contact.appointments)
  ? contact.appointments
  : [];

const primaryPhone =
  phones.find(
    phone => phone?.is_primary === true
  ) ??
  phones[0] ??
  null;

return [
  {
    json: {
      status: 'resolved',

      contact: {
        id: contact.id,
        first_name: contact.first_name ?? null,
        last_name: contact.last_name ?? null,
        company: contact.company ?? null,
        email: contact.email ?? null,
        status: contact.status ?? null,
        notes: contact.notes ?? null,
        created_at: contact.created_at ?? null,
        updated_at: contact.updated_at ?? null
      },

      primary_phone: primaryPhone,

      phones,

      tasks,

      appointments
    }
  }
];
